package main

import (
	"context"
	"sync"
	"unsafe"

	"github.com/hashicorp/terraform-plugin-sdk/v2/diag"
	"github.com/hashicorp/terraform-plugin-sdk/v2/helper/schema"
)

// #include <stdlib.h>
import "C"

type connectionPool struct {
	mu      sync.Mutex
	conns   map[string]unsafe.Pointer
	freed   map[string]bool
}

var pool = &connectionPool{
	conns: make(map[string]unsafe.Pointer),
	freed: make(map[string]bool),
}

func (p *connectionPool) Allocate(id string, size int) unsafe.Pointer {
	p.mu.Lock()
	defer p.mu.Unlock()
	ptr := C.malloc(C.size_t(size))
	p.conns[id] = ptr
	p.freed[id] = false
	return ptr
}

func (p *connectionPool) Release(id string) {
	p.mu.Lock()
	ptr, exists := p.conns[id]
	p.mu.Unlock()

	if exists && ptr != nil {
		C.free(ptr)
		// BUG: Race condition - freed flag not set atomically with free
		// Another goroutine can call Release again before freed is set
		p.mu.Lock()
		p.freed[id] = true
		p.mu.Unlock()
	}
}

func resourceCustomInfra() *schema.Resource {
	return &schema.Resource{
		CreateContext: resourceCustomInfraCreate,
		ReadContext:   resourceCustomInfraRead,
		DeleteContext: resourceCustomInfraDelete,
		Schema: map[string]*schema.Schema{
			"name": {
				Type:     schema.TypeString,
				Required: true,
				ForceNew: true,
			},
			"config_payload": {
				Type:      schema.TypeString,
				Required:  true,
				ForceNew:  true,
				Sensitive: true,
			},
			"parallel_destroy": {
				Type:     schema.TypeBool,
				Optional: true,
				Default:  false,
			},
		},
	}
}

func resourceCustomInfraCreate(ctx context.Context, d *schema.ResourceData, meta interface{}) diag.Diagnostics {
	name := d.Get("name").(string)
	payload := d.Get("config_payload").(string)

	ptr := pool.Allocate(name, len(payload))
	if ptr == nil {
		return diag.Errorf("allocation failed for resource %s", name)
	}

	// Copy payload into native buffer for processing
	cPayload := C.CString(payload)
	C.free(unsafe.Pointer(cPayload))

	d.SetId(name)
	return nil
}

func resourceCustomInfraRead(ctx context.Context, d *schema.ResourceData, meta interface{}) diag.Diagnostics {
	return nil
}

func resourceCustomInfraDelete(ctx context.Context, d *schema.ResourceData, meta interface{}) diag.Diagnostics {
	id := d.Id()
	parallelDestroy := d.Get("parallel_destroy").(bool)

	if parallelDestroy {
		// When parallel_destroy is true, multiple goroutines may call Release
		// on the same resource during terraform destroy -parallelism=N
		var wg sync.WaitGroup
		wg.Add(2)
		go func() {
			defer wg.Done()
			pool.Release(id)
		}()
		go func() {
			defer wg.Done()
			pool.Release(id)
		}()
		wg.Wait()
	} else {
		pool.Release(id)
	}

	d.SetId("")
	return nil
}

func Provider() *schema.Provider {
	return &schema.Provider{
		ResourcesMap: map[string]*schema.Resource{
			"custom_infra": resourceCustomInfra(),
		},
	}
}

func main() {
	// Provider serves via gRPC on localhost:PORT
	// Terraform core connects to this process
}
